def memoize(*args, **kwargs):
    """@memoize(key_func=None). Makes decorated function memoize its results.

    If key_func is specified uses key_func(*func_args, **func_kwargs) as memory key.
    Otherwise uses args + tuple(sorted(kwargs.items()))

    Exposes its memory via .memory attribute.
    """
    if args:
        assert len(args) == 1
        assert not kwargs
        return memoize()(args[0])
    compute_key_func = kwargs.pop('key_func', None)
    if kwargs:
        raise TypeError('memoize() got unexpected keyword arguments: %s', ', '.join(kwargs))

    def decorator(target_function):
        result_store = {}

        @wraps(target_function)
        def cached_func(*call_args, **call_kwargs):
            # NOTE: we inline this here but not in @cache,
            #       since @memoize also targets microoptimizations.
            if compute_key_func is not None:
                current_key = compute_key_func(*call_args, **call_kwargs)
            elif call_kwargs:
                current_key = call_args + tuple(sorted(call_kwargs.items()))
            else:
                current_key = call_args

            try:
                return result_store[current_key]
            except KeyError:
                try:
                    computed_value = target_function(*call_args, **call_kwargs)
                    result_store[current_key] = computed_value
                    return computed_value
                except SkipMemoization as skip_exception:
                    if skip_exception.args:
                        return skip_exception.args[0]
                    else:
                        return None

        cached_func.memory = result_store
        cached_func.skip = SkipMemoization

        def clear_cached_entry(*entry_args, **entry_kwargs):
            if compute_key_func is not None:
                entry_key = compute_key_func(*entry_args, **entry_kwargs)
            elif entry_kwargs:
                entry_key = entry_args + tuple(sorted(entry_kwargs.items()))
            else:
                entry_key = entry_args
            result_store.pop(entry_key, None)
        cached_func.invalidate = clear_cached_entry

        def clear_all_cached_entries():
            result_store.clear()
        cached_func.invalidate_all = clear_all_cached_entries

        return cached_func
    return decorator
