def cache(timeout, key_func=None):
    """Caches a function results for timeout seconds."""
    ttl_duration = timeout
    if isinstance(ttl_duration, int):
        ttl_duration = timedelta(seconds=ttl_duration)

    if key_func is None:
        def compute_cache_key(*incoming_args, **incoming_kwargs):
            if incoming_kwargs:
                return incoming_args + tuple(sorted(incoming_kwargs.items()))
            else:
                return incoming_args
        key_func = compute_cache_key

    def decorator(target_function):
        ttl_store = {}

        @wraps(target_function)
        def cached_func(*call_args, **call_kwargs):
            lookup_key = key_func(*call_args, **call_kwargs)
            if lookup_key in ttl_store:
                fetched_result, recorded_time = ttl_store[lookup_key]
                if datetime.now() - recorded_time < ttl_duration:
                    return fetched_result
                else:
                    del ttl_store[lookup_key]

            fetched_result = target_function(*call_args, **call_kwargs)
            ttl_store[lookup_key] = fetched_result, datetime.now()
            return fetched_result

        cached_func.memory = ttl_store
        cached_func.skip = SkipMemoization

        def remove_ttl_entry(*entry_args, **entry_kwargs):
            ttl_store.pop(key_func(*entry_args, **entry_kwargs), None)
        cached_func.invalidate = remove_ttl_entry

        def purge_ttl_store():
            ttl_store.clear()
        cached_func.invalidate_all = purge_ttl_store

        return cached_func
    return decorator
```
